import{_ as t,a0 as l,w as r,s as o,ao as d,I as p,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在 Linux 上查看用户的創建日期 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上查看用户的創建日期 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上查看用户的創建日期 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上查看用户的創建日期 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180412 How To Check User Created Date On Linux","title":"如何在 Linux 上查看用户的創建日期","tag":"201805","desc":""},"relativePath":"201805/20180412 How To Check User Created Date On Linux.md","filePath":"[post].md"}'),h={name:"201805/20180412 How To Check User Created Date On Linux.md"};function c(u,s,g,k,b,m){const e=l("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-linux-上查看用户的創建日期" tabindex="-1">如何在 Linux 上查看用户的創建日期 <a class="header-anchor" href="#如何在-linux-上查看用户的創建日期" aria-label="Permalink to “如何在 Linux 上查看用户的創建日期”">​</a></h1><p>你知道嗎，如何在 Linux 系統上查看帳户的創建日期？如果知道，那麼有些什麼辦法。</p><p>你成功了麼？如果是的話，該怎麼做？</p><p>基本上 Linux 系統不會跟蹤這些信息，因此，獲取這些信息的替代方法是什麼？</p><p>你可能會問為什麼我要查看這個？</p><p>是的，在某些情況下，你可能需要查看這些信息，那時就會對你會有幫助。</p><p>可以使用以下 7 種方法進行驗證。</p><ul><li>使用 <code>/var/log/secure</code></li><li>使用 <code>aureport</code> 工具</li><li>使用 <code>.bash_logout</code></li><li>使用 <code>chage</code> 命令</li><li>使用 <code>useradd</code> 命令</li><li>使用 <code>passwd</code> 命令</li><li>使用 <code>last</code> 命令</li></ul><h3 id="方式-1-使用-var-log-secure" tabindex="-1">方式 1：使用 /var/log/secure <a class="header-anchor" href="#方式-1-使用-var-log-secure" aria-label="Permalink to “方式 1：使用 /var/log/secure”">​</a></h3><p>它存儲所有安全相關的消息，包括身份驗證失敗和授權特權。它還會通過系統安全守護進程跟蹤 <code>sudo</code> 登錄、SSH 登錄和其他錯誤記錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep prakash /var/log/secure</span></span>
<span class="line"><span>Apr 12 04:07:18 centos.2daygeek.com useradd[21263]: new group: name=prakash, GID=501</span></span>
<span class="line"><span>Apr 12 04:07:18 centos.2daygeek.com useradd[21263]: new user: name=prakash, UID=501, GID=501, home=/home/prakash, shell=/bin/bash</span></span>
<span class="line"><span>Apr 12 04:07:34 centos.2daygeek.com passwd: pam_unix(passwd:chauthtok): password changed for prakash</span></span>
<span class="line"><span>Apr 12 04:08:32 centos.2daygeek.com sshd[21269]: Accepted password for prakash from 103.5.134.167 port 60554 ssh2</span></span>
<span class="line"><span>Apr 12 04:08:32 centos.2daygeek.com sshd[21269]: pam_unix(sshd:session): session opened for user prakash by (uid=0)</span></span></code></pre></div><h3 id="方式-2-使用-aureport-工具" tabindex="-1">方式 2：使用 aureport 工具 <a class="header-anchor" href="#方式-2-使用-aureport-工具" aria-label="Permalink to “方式 2：使用 aureport 工具”">​</a></h3><p><code>aureport</code> 工具可以根據記錄在審計日誌中的事件記錄生成彙總和柱狀報告。默認情況下，它會查詢 <code>/var/log/audit/</code> 目錄中的所有 <code>audit.log</code> 文件來創建報告。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># aureport --auth | grep prakash</span></span>
<span class="line"><span>46. 04/12/2018 04:08:32 prakash 103.5.134.167 ssh /usr/sbin/sshd yes 288</span></span>
<span class="line"><span>47. 04/12/2018 04:08:32 prakash 103.5.134.167 ssh /usr/sbin/sshd yes 291</span></span></code></pre></div><h3 id="方式-3-使用-bash-logout" tabindex="-1">方式 3：使用 .bash_logout <a class="header-anchor" href="#方式-3-使用-bash-logout" aria-label="Permalink to “方式 3：使用 .bash_logout”">​</a></h3><p>家目錄中的 <code>.bash_logout</code> 對 bash 有特殊的含義，它提供了一種在用户退出系統時執行命令的方式。</p><p>我們可以查看用户家目錄中 <code>.bash_logout</code> 的更改日期。該文件是在用户第一次註銷時創建的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stat /home/prakash/.bash_logout</span></span>
<span class="line"><span> File: \`/home/prakash/.bash_logout&#39;</span></span>
<span class="line"><span> Size: 18 Blocks: 8 IO Block: 4096 regular file</span></span>
<span class="line"><span>Device: 801h/2049d Inode: 256153 Links: 1</span></span>
<span class="line"><span>Access: (0644/-rw-r--r--) Uid: ( 501/ prakash) Gid: ( 501/ prakash)</span></span>
<span class="line"><span>Access: 2017-03-22 20:15:00.000000000 -0400</span></span>
<span class="line"><span>Modify: 2017-03-22 20:15:00.000000000 -0400</span></span>
<span class="line"><span>Change: 2018-04-12 04:07:18.283000323 -0400</span></span></code></pre></div><h3 id="方式-4-使用-chage-命令" tabindex="-1">方式 4：使用 chage 命令 <a class="header-anchor" href="#方式-4-使用-chage-命令" aria-label="Permalink to “方式 4：使用 chage 命令”">​</a></h3><p><code>chage</code> 意即 “change age”。該命令讓用户管理密碼過期信息。<code>chage</code> 命令可以修改上次密碼更改日期後需要更改密碼的天數。</p><p>系統使用此信息來確定用户何時必須更改其密碼。如果用户自帳户創建日期以來沒有更改密碼，這個就有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chage --list prakash</span></span>
<span class="line"><span>Last password change : Apr 12, 2018</span></span>
<span class="line"><span>Password expires : never</span></span>
<span class="line"><span>Password inactive : never</span></span>
<span class="line"><span>Account expires : never</span></span>
<span class="line"><span>Minimum number of days between password change : 0</span></span>
<span class="line"><span>Maximum number of days between password change : 99999</span></span>
<span class="line"><span>Number of days of warning before password expires : 7</span></span></code></pre></div><h3 id="方式-5-使用-useradd-命令" tabindex="-1">方式 5：使用 useradd 命令 <a class="header-anchor" href="#方式-5-使用-useradd-命令" aria-label="Permalink to “方式 5：使用 useradd 命令”">​</a></h3><p><code>useradd</code> 命令用於在 Linux 中創建新帳户。默認情況下，它不會添加用户創建日期，我們必須使用 “備註” 選項添加日期。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># useradd -m prakash -c \`date +%Y/%m/%d\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span># grep prakash /etc/passwd</span></span>
<span class="line"><span>prakash:x:501:501:2018/04/12:/home/prakash:/bin/bash</span></span></code></pre></div><h3 id="方式-6-使用-passwd-命令" tabindex="-1">方式 6：使用 passwd 命令 <a class="header-anchor" href="#方式-6-使用-passwd-命令" aria-label="Permalink to “方式 6：使用 passwd 命令”">​</a></h3><p><code>passwd</code> 命令用於將密碼分配給本地帳户或用户。如果用户在帳户創建後沒有修改密碼，那麼可以使用 <code>passwd</code> 命令查看最後一次密碼修改的日期。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># passwd -S prakash</span></span>
<span class="line"><span>prakash PS 2018-04-11 0 99999 7 -1 (Password set, MD5 crypt.)</span></span></code></pre></div><h3 id="方式-7-使用-last-命令" tabindex="-1">方式 7：使用 last 命令 <a class="header-anchor" href="#方式-7-使用-last-命令" aria-label="Permalink to “方式 7：使用 last 命令”">​</a></h3><p><code>last</code> 命令讀取 <code>/var/log/wtmp</code>，並顯示自該文件創建以來所有登錄（和退出）用户的列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># last | grep &quot;prakash&quot;</span></span>
<span class="line"><span>prakash pts/2 103.5.134.167 Thu Apr 12 04:08 still logged in</span></span></code></pre></div><hr>`,32)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.2daygeek.com/how-to-check-user-created-date-on-linux/"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.2daygeek.com/how-to-check-user-created-date-on-linux/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"https://www.2daygeek.com/author/prakash/"},{default:i(()=>[...s[2]||(s[2]=[a("Prakash Subramanian",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=t(h,[["render",c]]);export{w as __pageData,y as default};
